'use strict';
const fs=require('fs'),path=require('path'),http=require('http'),zlib=require('zlib'),assert=require('assert/strict');
const {chromium}=require('playwright');const root=path.resolve(__dirname,'..');
function pixels(png){let width,height,type,idat=[];for(let p=8;p<png.length;){const n=png.readUInt32BE(p),kind=png.toString('ascii',p+4,p+8),d=png.subarray(p+8,p+8+n);if(kind==='IHDR'){width=d.readUInt32BE(0);height=d.readUInt32BE(4);type=d[9];assert.equal(d[8],8)}if(kind==='IDAT')idat.push(d);p+=n+12;}assert.equal(type,6,'transparent screenshot requires RGBA');const bytes=zlib.inflateSync(Buffer.concat(idat)),stride=width*4,out=Buffer.alloc(stride*height);let pos=0;for(let y=0;y<height;y++){const filter=bytes[pos++];for(let x=0;x<stride;x++){const a=x>=4?out[y*stride+x-4]:0,b=y?out[(y-1)*stride+x]:0,c=y&&x>=4?out[(y-1)*stride+x-4]:0;let v=bytes[pos++];if(filter===1)v+=a;else if(filter===2)v+=b;else if(filter===3)v+=Math.floor((a+b)/2);else if(filter===4){let q=a+b-c,pa=Math.abs(q-a),pb=Math.abs(q-b),pc=Math.abs(q-c);v+=pa<=pb&&pa<=pc?a:pb<=pc?b:c;}else assert.equal(filter,0);out[y*stride+x]=v&255;}}return {width,height,alpha:(x,y)=>out[(y*width+x)*4+3]};}
const server=http.createServer((req,res)=>{const url=new URL(req.url,'http://localhost');if(url.pathname==='/fixture'){res.writeHead(200,{'Content-Type':'text/html'}).end('<!doctype html><html><head><link rel="stylesheet" href="/brand.css"><style>html,body{background:transparent!important;margin:0;padding:16px}.ma-brand-home-link{background:linear-gradient(red,blue)!important}img{width:128px!important;height:128px!important;display:block!important;transform:none!important;box-shadow:none!important}a{display:block;width:max-content}</style></head><body><a class="ma-brand-home-link"><img id="test-brand" class="ma-brand-orb" src="/assets/brand/matchapp-icon-approved.png"></a></body></html>');return}const f=path.resolve(root,'.'+url.pathname);if(!f.startsWith(root+path.sep)){res.writeHead(403).end();return}try{res.writeHead(200,{'Content-Type':f.endsWith('.css')?'text/css':f.endsWith('.svg')?'image/svg+xml':'image/png'});fs.createReadStream(f).pipe(res)}catch{res.writeHead(404).end()}});
(async()=>{await new Promise(r=>server.listen(0,'127.0.0.1',r));const b=await chromium.launch({headless:true});try{const p=await b.newPage({viewport:{width:390,height:300}});await p.goto('http://127.0.0.1:'+server.address().port+'/fixture');await p.locator('#test-brand').evaluate(e=>e.decode());const styles=await p.locator('.ma-brand-home-link').evaluate(e=>({background:getComputedStyle(e).backgroundImage,shadow:getComputedStyle(e).boxShadow,mask:getComputedStyle(e.querySelector('img')).maskImage}));assert.equal(styles.background,'none','generic button gradient must not paint behind brand');assert.equal(styles.shadow,'none');assert.match(styles.mask,/approved-mask/);const png=await p.locator('#test-brand').screenshot({omitBackground:true});const a=pixels(png);for(const [x,y]of[[2,2],[64,2],[2,64],[125,64],[64,125]])assert.equal(a.alpha(x,y),0,'source canvas leaked at '+x+','+y);assert(a.alpha(64,64)>250,'approved mark must remain visible');const dir=path.join(root,'docs/design-reviews/20261014');fs.writeFileSync(path.join(dir,'brand-matte-audit.json'),JSON.stringify({pass:true,sourceUnchanged:true,styles,transparentExteriorSamples:5,visibleMark:true},null,2));fs.writeFileSync(path.join(dir,'screenshots/approved-logo-no-matte.png'),png);console.log('PASS rendered approved artwork: transparent outer canvas, visible original mark, no rectangular brand-link gradient');}finally{await b.close();server.close()}})().catch(e=>{console.error(e.stack);process.exitCode=1});